.segment	"CODE"

.proc	_add_score: near

.segment	"CODE"

;
; score += score_to_add;
;
	lda     _score_to_add
	clc
	adc     _score
	sta     _score
	lda     #$00
	adc     _score+1
	sta     _score+1
;
; while(score_to_add > 0){
;
	jmp     L4FFE
;
; --score_to_add;
;
L4FFB:	dec     _score_to_add
;
; ones_score = next_digit10[ones_score];
;
	ldy     _ones_score
	lda     _next_digit10,y
	sta     _ones_score
;
; if(ones_score != 0){
;
	lda     _ones_score
;
; continue;
;
	bne     L4FFE
;
; tens_score = next_digit10[tens_score];
;
	ldy     _tens_score
	lda     _next_digit10,y
	sta     _tens_score
;
; if(tens_score != 0){
;
	lda     _tens_score
;
; continue;
;
	bne     L4FFE
;
; hundreds_score = next_digit10[hundreds_score];
;
	ldy     _hundreds_score
	lda     _next_digit10,y
	sta     _hundreds_score
;
; if(hundreds_score != 0){
;
	lda     _hundreds_score
;
; continue;
;
	bne     L4FFE
;
; thousands_score = next_digit10[thousands_score];
;
	ldy     _thousands_score
	lda     _next_digit10,y
	sta     _thousands_score
;
; if(thousands_score == 0 && ten_thousands_score < 9){
;
	lda     _thousands_score
	bne     L4FFE
	lda     _ten_thousands_score
	cmp     #$09
	bcs     L4FFE
;
; ++ten_thousands_score;
;
	inc     _ten_thousands_score
;
; while(score_to_add > 0){
;
L4FFE:	lda     _score_to_add
	bne     L4FFB
;
; }
;
	rts

.endproc

